type CharacterText = Annotated[str, Field(min_length=1)]
"""
null when the verbatim words have been cleared or the character's text was not received / 発言そのものが消去済み、または登場人物のテキストを受け取っていないときは null
"""


class LastTurn(BaseModel):
    """
    The last turn before disconnecting (section 4) / 切断前の最後のターン（第 4 節）
    """

    model_config = ConfigDict(
        extra="forbid",
        validate_by_name=True,
        arbitrary_types_allowed=True,
    )
    turnId: TurnId
    character: CharacterId | None
    """
    Whom it was with; a turn in which the player states a plan by voice at the end of the act (activity_start purpose = act_plan) has no character and is null (decided in the C-1 review) / 誰と話したか。幕末に声でプランを述べるターン（activity_start purpose = act_plan）には登場人物がいないので null（C-1 レビューで決定）
    """
    status: Literal["settled", "pending", "lost"]
    """
    settled / pending (the narrator is still judging) / lost (the character had not finished speaking at disconnect: not judged, no turn_settled, v1.0.3) / settled / pending（ナレーターがまだ判定中）/ lost（切断時に登場人物がまだ話し終えていなかった：判定せず、turn_settled もない。v1.0.3）
    """
    playerText: PlayerText | None
    """
    null for turns whose verbatim words have been cleared / 発言そのものが消去済みのターンでは null
    """
    characterText: CharacterText | None
    """
    null when the verbatim words have been cleared or the character's text was not received / 発言そのものが消去済み、または登場人物のテキストを受け取っていないときは null
    """


