class MemoryChange(BaseModel):
    """
    commit.memories[] (3.4); the frontend uses it to invalidate and refetch the 記憶帳 query. added and updated must carry text and kind; deleted does not (decided in the C-1 review) / commit.memories[]（3.4）。フロントエンドはこれをもとに記憶帳のクエリを無効化して再取得する。added と updated は text と kind が必須、deleted には付けない（C-1 レビューで決定）
    """

    model_config = ConfigDict(
        extra="forbid",
        validate_by_name=True,
        arbitrary_types_allowed=True,
    )
    character: CharacterId
    change: Literal["added", "updated", "deleted"]
    memoryId: MemoryId
    text: str | None = None
    """
    One Japanese sentence from the character's point of view, shown in the 記憶帳; no real-world personal information; cleared after deletion / 登場人物の視点による日本語の一文。記憶帳に表示する。現実の個人情報は含めない。削除後は空にする
    """
    kind: Literal["promise", "help", "harm", "shared-moment", "claim", "impression"] | None = None
    relationLabel: str
    """
    Mapped from the trust range (the table in section 4) / trust の区間から対応付ける（第 4 節の表）
    """
    relationLevel: Literal[1, 2, 3, 4, 5]
    """
    (1.5) The level within the same range; called relationLevel in the API / （1.5）同じ区間内の段階。API では relationLevel と呼ぶ
    """


