class SetPieceLineOption1(BaseModel):
    """
    (v1.0.4) One line of a set piece (3.14): the world model's SetPiece.lines, sent as is. narration = one line of 地の文; speaker + line = one pre-recorded line by this character, whose subtitle is line / （v1.0.4）固定演出の 1 行（3.14）：世界モデルの SetPiece.lines をそのまま送る。narration = 地の文 1 行。speaker + line = その登場人物の事前収録セリフ 1 つで、字幕は line
    """

    model_config = ConfigDict(
        extra="forbid",
        validate_by_name=True,
    )
    narration: Annotated[str, Field(min_length=1)]
    """
    One line of 地の文 (in Japanese) / 地の文 1 行（日本語）
    """


class SetPieceLineOption2(BaseModel):
    """
    (v1.0.4) One line of a set piece (3.14): the world model's SetPiece.lines, sent as is. narration = one line of 地の文; speaker + line = one pre-recorded line by this character, whose subtitle is line / （v1.0.4）固定演出の 1 行（3.14）：世界モデルの SetPiece.lines をそのまま送る。narration = 地の文 1 行。speaker + line = その登場人物の事前収録セリフ 1 つで、字幕は line
    """

    model_config = ConfigDict(
        extra="forbid",
        validate_by_name=True,
        arbitrary_types_allowed=True,
    )
    speaker: CharacterId
    line: Annotated[str, Field(min_length=1)]
    """
    A pre-recorded line, also the subtitle (in Japanese) / 事前収録セリフ。字幕も兼ねる（日本語）
    """


type SetPieceLine = Annotated[SetPieceLineOption1 | SetPieceLineOption2, Field(title="SetPieceLine")]
"""
(v1.0.4) One line of a set piece (3.14): the world model's SetPiece.lines, sent as is. narration = one line of 地の文; speaker + line = one pre-recorded line by this character, whose subtitle is line / （v1.0.4）固定演出の 1 行（3.14）：世界モデルの SetPiece.lines をそのまま送る。narration = 地の文 1 行。speaker + line = その登場人物の事前収録セリフ 1 つで、字幕は line
"""


class SetPieceMessage(BaseModel):
    """
    (v1.0.4) Set piece (3.14, contract 2.11): pre-written 地の文 and characters' pre-recorded lines, played in order. Not an event, does not take a seq, and is not resent if missed during a disconnect / （v1.0.4）固定演出（3.14、契約 2.11）：書き上げ済みの地の文と登場人物の事前収録セリフを順に演じる。イベントではなく seq を消費せず、切断中に受け取れなかったものは再送しない
    """

    model_config = ConfigDict(
        extra="forbid",
        validate_by_name=True,
        arbitrary_types_allowed=True,
    )
    type: Literal["set_piece"] = "set_piece"
    pieceId: SetPieceId
    lines: Annotated[list[SetPieceLine], Field(min_length=1)]
    """
    A character's line plays the manifest's setPieceVoices["<pieceId>/<n>"] (n = position in lines, starting at 1, with 地の文 lines counted too) / 登場人物のセリフは manifest の setPieceVoices["<pieceId>/<番号>"] を再生する（番号 = lines 内の位置。1 から始まり、地の文も数える）
    """


type SetPieceVoiceKey = Annotated[
    str,
    Field(
        pattern="^piece\\.[a-z0-9]+(?:[.-][a-z0-9]+)*/[1-9][0-9]*$",
        title="SetPieceVoiceKey",
    ),
]
"""
(v1.0.4) Key of manifest.setPieceVoices: 「{set piece ID}/{n}」, with n starting at 1, e.g. piece.gate-taken/2 / （v1.0.4）manifest.setPieceVoices のキー：「{固定演出 ID}/{番号}」。番号は 1 から始まる。例：piece.gate-taken/2
"""


class SituationalAction(BaseModel):
    """
    Affordances available right now (2.3, 3.8) / いま実行できる状況アクション（2.3、3.8）
    """

    model_config = ConfigDict(
        extra="forbid",
        validate_by_name=True,
        arbitrary_types_allowed=True,
    )
    actionId: ActionId
    kind: Literal["examine", "give", "follow", "block", "help", "wait", "go", "shortcut", "run-together", "hasten"]
    target: CharacterId | None = None
    """
    Target character; omitted (not null) for actions without a target (such as wait; Affordance.target is optional in the world model) (decided in the C-1 review) / 対象の登場人物。対象のないアクション（wait など。世界モデルの Affordance.target は任意）では省略し、null にはしない（C-1 レビューで決定）
    """
    label: str
    """
    Verb phrase on the button (in Japanese), without the time it takes / ボタン上の動詞句（日本語）。所要時間は書かない
    """
    estimatedMinutes: Minutes
    melos: Literal["delay", "hasten"] | None
    """
    Effect on Melos in the fourth act (S-036, S-038); null if none / 第四幕でのメロスへの影響（S-036、S-038）。なければ null
    """
    melosMinutes: int | None
    """
    null for actions without melos / melos のないアクションでは null
    """
    melosInTime: bool | None
    """
    null for actions without melos / melos のないアクションでは null
    """
    enabled: bool


